	"strconv"
	"strings"
)

type Request struct {
	Expression string `json:"expression"`
}

type Response struct {
	Result string `json:"result"`
}

func calculate(expression string) (string, error) {
	// Simple evaluation of the expression
	// This is a naive implementation and should be improved for production use
	tokens := strings.Fields(expression)
	if len(tokens) == 0 {
		return "", fmt.Errorf("invalid expression")
	}

	result, err := strconv.ParseFloat(tokens[0], 64)
	if err != nil {
		return "", fmt.Errorf("invalid expression")
	}

	for i := 1; i < len(tokens); i += 2 {
		operator := tokens[i]
		if i+1 >= len(tokens) {
			return "", fmt.Errorf("invalid expression")
		}
		nextValue, err := strconv.ParseFloat(tokens[i+1], 64)
		if err != nil {
			return "", fmt.Errorf("invalid expression")
		}

		switch operator {
		case "+":
			result += nextValue
		case "-":
			result -= nextValue
		case "*":
			result *= nextValue
		case "/":
			if nextValue == 0 {
				return "", fmt.Errorf("division by zero")
			}
			result /= nextValue
		default:
			return "", fmt.Errorf("invalid operator")
		}
	}

	return fmt.Sprintf("%g", result), nil
}

func calculatorHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid input", http.StatusBadRequest)
		return
	}

	result, err := calculate(req.Expression)
	if err != nil {
		http.Error(w, "Invalid input", http.StatusBadRequest)
		return
	}

	resp := Response{Result: result}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/calculator", calculatorHandler)
	fmt.Println("Server is running on http://0.0.0.0:5000")
	if err := http.ListenAndServe("0.0.0.0:5000", nil); err != nil {
		fmt.Println("Failed to start server:", err)
	}
}
